blDispReason.Text = Session["Leave_Reason"].ToString();          pnlResult.Visible = true;         lblMessage.Text = "Leave applied successfully!"; lblMessage.ForeColor = System.Drawing.Color.Green; }  6. SESSION CLEAR: Logout protected void btnLogout_Click(object sender, EventArgs e) { } } Session.Clear(); Session.Abandon(); Response.Redirect("Login.aspx"); 
